  svg.appendChild(el("path",{d:fedD, fill:"none", stroke:"#6b7280", "stroke-width":"1.6"}));

  for (var i=0;i<n;i++){
    svg.appendChild(el("text",{x:xp(i),y:H-margin.bottom+16,"text-anchor":"middle","font-size":"8","fill":"#999999"}, data[i].m));
  }

  svg.appendChild(el("text",{x:xp(1),y:yp(data[1].boc)+14,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#1a3560"}, "BOC: HOLDING"));
  svg.appendChild(el("text",{x:xp(4),y:yp(data[4].fed)-10,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#6b7280"}, "FED: WARSH ERA"));

  var lastX = xp(n-1), lastYf = yp(data[n-1].fed), lastYb = yp(data[n-1].boc);
  var pillW = 58, pillH = 16;
