  if (pillX < margin.left) pillX = lastX + 6;
  svg.appendChild(el("circle",{cx:lastX, cy:lastYf, r:4, fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111111"}, "3.625%"));

  var bocPillX = lastX + 6;
  var bocPillY = lastYb - pillH/2;
  svg.appendChild(el("circle",{cx:lastX, cy:lastYb, r:4, fill:"#1a3560"}));
  svg.appendChild(el("rect",{x:bocPillX,y:bocPillY,width:pillW,height:pillH,rx:3,fill:"#ffffff",stroke:"#1a3560"}));
  svg.appendChild(el("text",{x:bocPillX+pillW/2,y:bocPillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#1a3560"}, "2.25%"));

  if (_cs && _cs.parentNode) { _cs.parentNode.appendChild(svg); }
