  for (var g=0; g<=5; g++){
    var gv = minV + g*(maxV-minV)/5;
    var gy = yp(gv);
    svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:gy,y2:gy,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(el("text",{x:margin.left-6,y:gy+3,"text-anchor":"end","font-size":"8.5","fill":"#aaaaaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, Math.round(gv)));
  }

  svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:yp(110),y2:yp(110),stroke:"#7a3030","stroke-dasharray":"3,3"}));
  svg.appendChild(el("text",{x:margin.left+10,y:yp(110)-5,"text-anchor":"start","font-size":"7","font-weight":"700","fill":"#7a3030"}, "PRE-WAR AVERAGE: 110/DAY"));

  var mouI = 9;
  var bandX1 = xp(mouI-0.4), bandX2 = xp(mouI+0.6);
  svg.appendChild(el("rect",{x:bandX1,y:margin.top,width:(bandX2-bandX1),height:PH,fill:"#2e7d32","fill-opacity":"0.07"}));
  svg.appendChild(el("text",{x:(bandX1+bandX2)/2,y:margin.top+12,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#2e7d32"}, "MOU SIGNED"));

  var barW = PW/n * 0.55;
  for (var i=0;i<n;i++){
    var bx = xp(i) - barW/2;
    var by = yp(data[i].v);
    var bh = (margin.top+PH) - by;
    var fillColor = i >= mouI ? "#3a7a55" : "#4a5568";
    svg.appendChild(el("rect",{x:bx,y:by,width:barW,height:bh,fill:fillColor}));
  }

  for (var i=0;i<n;i+=3){
    svg.appendChild(el("text",{x:xp(i),y:H-margin.bottom+16,"text-anchor":"middle","font-size":"7.5","fill":"#999999"}, data[i].d));
  }

  var lastX = xp(n-1), lastY = yp(data[n-1].v);
  var pillW = 58, pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH/2;
  if (pillX < margin.left) pillX = lastX + 6;
  svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:4, fill:"#3a7a55"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111111"}, "24/DAY"));

  if (_cs && _cs.parentNode) { _cs.parentNode.appendChild(svg); }
})();
</script>
